typedef struct _iobuf {
   int  cnt;
   char *ptr;
   char *base;
   int  flag;
   int  fd;
} _FILE;

enum _flags {
   _READ   = 01,
   _WRITE  = 02,
   _UNBUF  = 04,
   _EOF    = 010,
   _ERR    = 020
};

_FILE _iob[OPEN_MAX] = {
   { 0, (char *) 0, (char *) 0, _READ, 0 },
   { 0, (char *) 0, (char *) 0, _WRITE, 1 },
   { 0, (char *) 0, (char *) 0, _WRITE | _UNBUF, 2 },
};

_FILE *Fopen(char *, char *);
int _fillbuf(_FILE *);
