    public class BDArchive
    {
        /// <summary>
        /// Simple structure of a file
        /// </summary>
        public struct File
        {
            public int NameLength;
            public string Name;
            public uint Offset;
            public uint Size;
            public MemoryStream ByteStream;
        }

        private File[] TableRecord;
        private int Records;

